27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "title")
39	    private String title;
40	
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "address_line1")
46	    private String addressLine1;
47	
48	    @Column(name = "address_line2")
49	    private String addressLine2;
50	
51	    @Column(name = "city")
52	    @NotEmpty
53	    private String city;
54	
55	    @Column(name = "telephone")
56	    @NotEmpty
57	    @Pattern(regexp = "^\\+[0-9]{8,15}$",
58	        message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
59	    private String telephone;
60	
61	    @Column(name = "email")
62	    private String email;
63	
64	    @Column(name = "postcode")
65	    private String postcode;
66	
67	    @Column(name = "registration_date", columnDefinition = "DATE")
68	    private LocalDate registrationDate;
69	
70	    @Column(name = "birth_date", columnDefinition = "DATE")
71	    private LocalDate birthDate;
72	
73	    @Column(name = "customer_code")
74	    private String customerCode;
75	
76	    @Column(name = "namesake_count")
77	    private Integer namesakeCount;
78	
79	    @Column(name = "bulk_signup_warning")
80	    private Boolean bulkSignupWarning;
81	
82	    @Column(name = "capacity_warning")
83	    private Boolean capacityWarning;
84	
85	    @Column(name = "household_size")
86	    private Integer householdSize;
87	
88	    @Column(name = "membership_level_cap")
89	    private Integer membershipLevelCap;
90	
91	    @Column(name = "possible_duplicate")
92	    private Boolean possibleDuplicate;
93	
94	    @Column(name = "possible_duplicate_of")
95	    private Integer possibleDuplicateOf;
96	
97	    @Column(name = "deleted", nullable = false)
98	    private boolean deleted = false;
99	
100	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
101	    private Set<Pet> pets;
102	
103	    public String getTitle() {
104	        return this.title;
105	    }
106	
107	    public void setTitle(String title) {
108	        this.title = title;
109	    }
110	
111	    public String getAddress() {
112	        return this.address;
113	    }
114	
115	    public void setAddress(String address) {
116	        this.address = address;
117	    }
118	
119	    public String getAddressLine1() {
120	        return this.addressLine1;
121	    }
122	
123	    public void setAddressLine1(String addressLine1) {
124	        this.addressLine1 = addressLine1;
125	    }
126	
127	    public String getAddressLine2() {
128	        return this.addressLine2;
129	    }
130	
131	    public void setAddressLine2(String addressLine2) {
132	        this.addressLine2 = addressLine2;
133	    }
134	
135	    public String getCity() {
136	        return this.city;
137	    }
138	
139	    public void setCity(String city) {
140	        this.city = city;
141	    }
142	
143	    public String getTelephone() {
144	        return this.telephone;
145	    }
146	
147	    public void setTelephone(String telephone) {
148	        this.telephone = telephone;
149	    }
150	
151	    public String getEmail() {
152	        return this.email;
153	    }
154	
155	    public void setEmail(String email) {
156	        this.email = email;
157	    }
158	
159	    public String getPostcode() {
160	        return this.postcode;
161	    }
162	
163	    public void setPostcode(String postcode) {
164	        this.postcode = postcode;
165	    }
166	
167	    public LocalDate getRegistrationDate() {
168	        return this.registrationDate;
169	    }
170	
171	    public void setRegistrationDate(LocalDate registrationDate) {
172	        this.registrationDate = registrationDate;
173	    }
174	
175	    public LocalDate getBirthDate() {
176	        return this.birthDate;
177	    }
178	
179	    public void setBirthDate(LocalDate birthDate) {
180	        this.birthDate = birthDate;
181	    }
182	
183	    public String getCustomerCode() {
184	        return this.customerCode;
185	    }
186	
187	    public void setCustomerCode(String customerCode) {
188	        this.customerCode = customerCode;
189	    }
190	
191	    public Integer getNamesakeCount() {
192	        return this.namesakeCount;
193	    }
194	
195	    public void setNamesakeCount(Integer namesakeCount) {
196	        this.namesakeCount = namesakeCount;
197	    }
198	
199	    public Boolean getBulkSignupWarning() {
200	        return this.bulkSignupWarning;
201	    }
202	
203	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
204	        this.bulkSignupWarning = bulkSignupWarning;
205	    }
206	
207	    public Boolean getCapacityWarning() {
208	        return this.capacityWarning;
209	    }
210	
211	    public void setCapacityWarning(Boolean capacityWarning) {
212	        this.capacityWarning = capacityWarning;
213	    }
214	
215	    public Integer getHouseholdSize() {
216	        return this.householdSize;
217	    }
218	
219	    public void setHouseholdSize(Integer householdSize) {
220	        this.householdSize = householdSize;
221	    }
222	
223	    public Integer getMembershipLevelCap() {
224	        return this.membershipLevelCap;
225	    }
226	
227	    public void setMembershipLevelCap(Integer membershipLevelCap) {
228	        this.membershipLevelCap = membershipLevelCap;
229	    }
230	
231	    public Boolean getPossibleDuplicate() {
232	        return this.possibleDuplicate;
233	    }
234	
235	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
236	        this.possibleDuplicate = possibleDuplicate;
237	    }
238	
239	    public Integer getPossibleDuplicateOf() {
240	        return this.possibleDuplicateOf;
241	    }
242	
243	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
244	        this.possibleDuplicateOf = possibleDuplicateOf;
245	    }
246	
247	    public boolean isDeleted() {
248	        return this.deleted;
249	    }
250	
251	    public void setDeleted(boolean deleted) {
252	        this.deleted = deleted;
253	    }
254	
255	    protected Set<Pet> getPetsInternal() {
256	        if (this.pets == null) {
257	            this.pets = new HashSet<>();
258	        }
259	        return this.pets;
260	    }
261	
262	    protected void setPetsInternal(Set<Pet> pets) {
263	        this.pets = pets;
264	    }
265	
266	    public List<Pet> getPets() {
267	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
268	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
269	        return Collections.unmodifiableList(sortedPets);
270	    }
271	
272	    public void setPets(List<Pet> pets) {
273	        this.pets = new HashSet<>(pets);
274	    }
275	
276	    public void addPet(Pet pet) {
277	        getPetsInternal().add(pet);
278	        pet.setOwner(this);
279	    }
280	
281	    /**
282	     * Return the Pet with the given name, or null if none found for this Owner.
283	     *
284	     * @param name to test
285	     * @return true if pet name is already in use
286	     */
287	    public Pet getPet(String name) {
288	        return getPet(name, false);
289	    }
290	
291	    /**
292	     * Return the Pet with the given name, or null if none found for this Owner.
293	     *
294	     * @param name to test
295	     * @return true if pet name is already in use
296	     */
297	    public Pet getPet(String name, boolean ignoreNew) {
298	        name = name.toLowerCase();
299	        for (Pet pet : getPetsInternal()) {
300	            if (!ignoreNew || !pet.isNew()) {
301	                String compName = pet.getName();
302	                compName = compName.toLowerCase();
303	                if (compName.equals(name)) {
304	                    return pet;
305	                }
306	            }
307	        }
308	        return null;
309	    }
310	
311	    public Pet getPet(Integer petId) {
312	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
313	    }
314	
315	    @Override
316	    public String toString() {
317	        return new ToStringCreator(this)
318	
319	            .append("id", this.getId())
320	            .append("new", this.isNew())
321	            .append("lastName", this.getLastName())
322	            .append("firstName", this.getFirstName())
323	            .append("address", this.address)
324	            .append("city", this.city)
325	            .append("telephone", this.telephone)
326	            .toString();
327	    }
328	}
