1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.nio.charset.StandardCharsets;
13	import java.security.MessageDigest;
14	import java.util.Collection;
15	import java.util.List;
16	import java.util.Locale;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public interface OwnerMapper {
23	
24	    /** Fixed city-to-region table used to derive an owner's region. */
25	    java.util.Map<String, String> CITY_REGION =
26	        java.util.Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
27	
28	    /** Fixed region-to-timezone table (IANA names) used to derive an owner's timezone. */
29	    java.util.Map<String, String> REGION_TIMEZONE =
30	        java.util.Map.of("NSW", "Australia/Sydney", "VIC", "Australia/Melbourne",
31	            "QLD", "Australia/Brisbane");
32	
33	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
34	    @Mapping(target = "displayName",
35	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
36	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
37	    @Mapping(target = "initials", expression = "java(initials(owner))")
38	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
39	    @Mapping(target = "householdId", expression = "java(householdId(owner))")
40	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
41	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
42	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
43	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
44	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
45	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
46	    @Mapping(target = "locality", expression = "java(locality(owner))")
47	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
48	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
49	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
50	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
51	    OwnerDto toOwnerDto(Owner owner);
52	
53	    /**
54	     * The owner's canonical API path, formatted '/api/owners/&lt;id&gt;'. Returns
55	     * {@code null} when the owner has not yet been assigned an id.
56	     */
57	    default String selfLink(Owner owner) {
58	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
59	    }
60	
61	    /**
62	     * The owner's salutation: the supplied title, a single space and the last name when a
63	     * title was supplied (e.g. 'DR Who'), or just the last name when no title (null or blank)
64	     * was given.
65	     */
66	    default String salutation(Owner owner) {
67	        String title = owner.getTitle();
68	        if (title == null || title.isBlank()) {
69	            return owner.getLastName();
70	        }
71	        return title + " " + owner.getLastName();
72	    }
73	
74	    /**
75	     * The owner's age band, derived from the supplied birthDate as at the
76	     * registrationDate: 'MINOR' when under 18, 'ADULT' when 18-64, and 'SENIOR' when
77	     * 65 or older. Returns {@code null} when no birthDate (or registrationDate) is
78	     * available, so the field is omitted for owners without a supplied birth date.
79	     */
80	    default String ageBand(Owner owner) {
81	        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
82	            return null;
83	        }
84	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
85	        if (age < 18) {
86	            return "MINOR";
87	        }
88	        if (age < 65) {
89	            return "ADULT";
90	        }
91	        return "SENIOR";
92	    }
93	
94	    /**
95	     * The owner's preferred contact channel: 'EMAIL' when an email address is present,
96	     * otherwise 'PHONE'.
97	     */
98	    default String contactPreference(Owner owner) {
99	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
100	        return hasEmail ? "EMAIL" : "PHONE";
101	    }
102	
103	    /**
104	     * The owner's region, read from the {@code <REGION>-<HASH8>} customer code assigned on
105	     * creation: the segment before the first '-'. Returns 'UNKNOWN' when no customer code has
106	     * been assigned (e.g. legacy owners predating the region-and-hash identity).
107	     */
108	    default String locality(Owner owner) {
109	        String code = owner.getCustomerCode();
110	        if (code != null) {
111	            int dash = code.indexOf('-');
112	            if (dash > 0) {
113	                return code.substring(0, dash);
114	            }
115	        }
116	        return "UNKNOWN";
117	    }
118	
119	    /**
120	     * The owner's IANA timezone, derived from its locality/region via the fixed
121	     * region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
122	     * QLD -> Australia/Brisbane). Returns {@code null} when the region is not one of
123	     * these, so the field is omitted for owners whose region is unknown.
124	     */
125	    default String timezone(Owner owner) {
126	        return REGION_TIMEZONE.get(locality(owner));
127	    }
128	
129	    /**
130	     * The owner's segment, formatted '&lt;TIER&gt;_&lt;AREA&gt;'. TIER is 'PREMIUM' when the
131	     * {@link #membershipLevel(Owner) membershipLevel} is 3 or more, otherwise 'STANDARD'. AREA is
132	     * 'METRO' when the {@link #locality(Owner) locality} is a known region (NSW, VIC or QLD),
133	     * otherwise 'REGIONAL'. One of 'PREMIUM_METRO', 'PREMIUM_REGIONAL', 'STANDARD_METRO' or
134	     * 'STANDARD_REGIONAL'.
135	     */
136	    default String ownerSegment(Owner owner) {
137	        String tier = membershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
138	        String area = REGION_TIMEZONE.containsKey(locality(owner)) ? "METRO" : "REGIONAL";
139	        return tier + "_" + area;
140	    }
141	
142	    /**
143	     * The owner's membership points. Starts at 0; gains 2 when an email address is present,
144	     * 1 when the owner has no namesakes (namesakeCount is 0), 2 for a household of 3 or more
145	     * (householdSize is 3 or greater), and 3 when the owner's tenure spans at least one
146	     * elapsed fiscal year (the current fiscal year, starting 1 July, is later than the
147	     * registrationDate's fiscal year). Because a newly created owner registers in the current
148	     * fiscal year, the tenure points are only earned once the fiscal year has rolled over
149	     * since registration.
150	     */
151	    default Integer membershipPoints(Owner owner) {
152	        int points = 0;
153	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
154	        if (hasEmail) {
155	            points += 2;
156	        }
157	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
158	        if (noNamesakes) {
159	            points += 1;
160	        }
161	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
162	            points += 2;
163	        }
164	        if (owner.getRegistrationDate() != null
165	            && fiscalEndYear(java.time.LocalDate.now())
166	                - fiscalEndYear(owner.getRegistrationDate()) >= 1) {
167	            points += 3;
168	        }
169	        return points;
170	    }
171	
172	    /**
173	     * The owner's numeric membership level, derived from {@link #membershipPoints(Owner)}:
174	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4
175	     * for 6 or more points.
176	     *
177	     * <p>The derived level is then capped by the owner's {@code membershipLevelCap} when one is
178	     * present: a new owner's level cannot exceed one above the current maximum membership level
179	     * among their existing household members, so the cap (recorded on the owner at creation as
180	     * that maximum plus one) is applied here. A {@code null} cap means the owner had no existing
181	     * household member, so no cap applies.
182	     */
183	    default Integer membershipLevel(Owner owner) {
184	        int points = membershipPoints(owner);
185	        int level;
186	        if (points <= 1) {
187	            level = 1;
188	        }
189	        else if (points <= 3) {
190	            level = 2;
191	        }
192	        else if (points <= 5) {
193	            level = 3;
194	        }
195	        else {
196	            level = 4;
197	        }
198	        Integer cap = owner.getMembershipLevelCap();
199	        if (cap != null && level > cap) {
200	            return cap;
201	        }
202	        return level;
203	    }
204	
205	    /**
206	     * A single Luhn check digit (0-9) computed over the digits contained in the owner's
207	     * customerCode. Returns {@code null} when the customerCode has not been assigned.
208	     */
209	    default Integer checkDigit(Owner owner) {
210	        if (owner.getCustomerCode() == null) {
211	            return null;
212	        }
213	        String s = owner.getCustomerCode();
214	        int sum = 0;
215	        boolean dbl = true;
216	        for (int i = s.length() - 1; i >= 0; i--) {
217	            char c = s.charAt(i);
218	            if (c < '0' || c > '9') {
219	                continue;
220	            }
221	            int d = c - '0';
222	            if (dbl) {
223	                d *= 2;
224	                if (d > 9) {
225	                    d -= 9;
226	                }
227	            }
228	            sum += d;
229	            dbl = !dbl;
230	        }
231	        return (10 - (sum % 10)) % 10;
232	    }
233	
234	    /**
235	     * The fiscal year, starting on 1 July, that a date falls in, expressed as the last two
236	     * digits of the calendar year in which the fiscal year ends. Dates on or after 1 July
237	     * belong to the fiscal year ending the following calendar year (e.g. 2026-08-10 -&gt; 27);
238	     * dates before 1 July belong to the fiscal year ending in the same calendar year
239	     * (e.g. 2026-03-01 -&gt; 26).
240	     */
241	    private static int fiscalEndYear(java.time.LocalDate date) {
242	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
243	    }
244	
245	    private static int fiscalYearOf(java.time.LocalDate date) {
246	        return fiscalEndYear(date) % 100;
247	    }
248	
249	    /**
250	     * The owner's fiscal year, formatted 'FY&lt;YY&gt;' where YY is the two-digit fiscal year
251	     * (starting 1 July) of the business-day-adjusted registrationDate (e.g. 'FY27'). Returns
252	     * {@code null} when no registrationDate is available.
253	     */
254	    default String fiscalYear(Owner owner) {
255	        if (owner.getRegistrationDate() == null) {
256	            return null;
257	        }
258	        return String.format("FY%02d", fiscalYearOf(owner.getRegistrationDate()));
259	    }
260	
261	    /**
262	     * The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY
263	     * is the two-digit fiscal year (starting 1 July) of the registrationDate
264	     * (e.g. 'NSW-1A2B3C4D-M27').
265	     */
266	    default String membershipNumber(Owner owner) {
267	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
268	            return null;
269	        }
270	        return String.format("%s-M%02d", owner.getCustomerCode(),
271	            fiscalYearOf(owner.getRegistrationDate()));
272	    }
273	
274	    /**
275	     * Known E.164 country calling codes used to split the stored telephone into its
276	     * country code and national number for display. Longer codes are matched first so a
277	     * '+61' number is not mistaken for a '+6...' one.
278	     */
279	    java.util.List<String> COUNTRY_CODES = java.util.List.of("61", "1");
280	
281	    /**
282	     * The stored E.164 telephone formatted for humans: the country code, a space, and the
283	     * national digits grouped in threes (e.g. '+61412345678' becomes '+61 412 345 678').
284	     * Returns the stored value unchanged when it is {@code null} or not in the expected
285	     * '+'-prefixed all-digits E.164 form.
286	     */
287	    default String telephoneDisplay(Owner owner) {
288	        String telephone = owner.getTelephone();
289	        if (telephone == null || !telephone.startsWith("+")) {
290	            return telephone;
291	        }
292	        String digits = telephone.substring(1);
293	        if (digits.isEmpty() || !digits.chars().allMatch(Character::isDigit)) {
294	            return telephone;
295	        }
296	        String countryCode = COUNTRY_CODES.stream()
297	            .filter(digits::startsWith)
298	            .findFirst()
299	            .orElse(digits.substring(0, 1));
300	        String national = digits.substring(countryCode.length());
301	        StringBuilder sb = new StringBuilder("+").append(countryCode);
302	        for (int i = 0; i < national.length(); i++) {
303	            if (i % 3 == 0) {
304	                sb.append(' ');
305	            }
306	            sb.append(national.charAt(i));
307	        }
308	        return sb.toString();
309	    }
310	
311	    /**
312	     * The upper-cased first letters of firstName and lastName, dot-separated with a
313	     * trailing dot, e.g. 'J.S.'.
314	     */
315	    default String initials(Owner owner) {
316	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
317	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
318	    }
319	
320	    /**
321	     * A stable identifier for the owner's household, derived deterministically from the
322	     * normalized last name and the postcode. Every owner sharing the same last name
323	     * (trimmed, lower-cased, whitespace collapsed) and postcode therefore receives the
324	     * same identifier: the first twelve upper-case hex characters of the SHA-256 of
325	     * '&lt;normalizedLastName&gt;|&lt;postcode&gt;'. A {@code null} postcode contributes
326	     * the empty string.
327	     */
328	    default String householdId(Owner owner) {
329	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
330	        String key = normalizeHouseholdKey(owner.getLastName()) + "|" + postcode;
331	        try {
332	            byte[] digest = MessageDigest.getInstance("SHA-256")
333	                .digest(key.getBytes(StandardCharsets.UTF_8));
334	            StringBuilder sb = new StringBuilder();
335	            for (int i = 0; i < 6; i++) {
336	                sb.append(String.format("%02X", digest[i]));
337	            }
338	            return sb.toString();
339	        }
340	        catch (java.security.NoSuchAlgorithmException e) {
341	            throw new IllegalStateException(e);
342	        }
343	    }
344	
345	    /**
346	     * The owner's derived identity key: the single value onto which all duplicate
347	     * detection is consolidated. It is the full lower-case hex SHA-256 digest of
348	     * '&lt;normalizedTelephone&gt;|&lt;lowerEmail&gt;|&lt;soundex(lastName)&gt;'.
349	     * The telephone and email are the owner's stored (already normalized) values;
350	     * a {@code null} email contributes the empty string, and the last name is reduced
351	     * to its Soundex code so surnames that sound alike share the same segment. Two
352	     * owners are duplicates only when their whole identity keys are equal.
353	     */
354	    default String identityKey(Owner owner) {
355	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
356	        String email = owner.getEmail() == null ? "" : owner.getEmail();
357	        String key = telephone + "|" + email + "|" + Soundex.of(owner.getLastName());
358	        try {
359	            byte[] digest = MessageDigest.getInstance("SHA-256")
360	                .digest(key.getBytes(StandardCharsets.UTF_8));
361	            StringBuilder sb = new StringBuilder(digest.length * 2);
362	            for (byte b : digest) {
363	                sb.append(String.format("%02x", b));
364	            }
365	            return sb.toString();
366	        }
367	        catch (java.security.NoSuchAlgorithmException e) {
368	            throw new IllegalStateException(e);
369	        }
370	    }
371	
372	    private static String normalizeHouseholdKey(String value) {
373	        if (value == null) {
374	            return "";
375	        }
376	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
377	    }
