331	    /**
332	     * The non-blank {@code Idempotency-Key} header of the current request, or {@code null} when
333	     * absent, blank, or there is no bound request.
334	     */
335	    private static String currentIdempotencyKey() {
336	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
337	        if (!(attributes instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttributes)) {
338	            return null;
339	        }
340	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
341	        return (key == null || key.isBlank()) ? null : key;
342	    }
343	
344	    /**
345	     * Validate and normalize the optional owner email in place.
346	     *
347	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
348	     * When present it must be a syntactically valid address; a valid address is
349	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
350	     * present but syntactically invalid, so the caller can reject with 400.
351	     */
352	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
353	        String email = ownerFieldsDto.getEmail();
354	        if (email == null || email.isBlank()) {
355	            ownerFieldsDto.setEmail(null);
356	            return true;
357	        }
358	        String normalized = email.trim().toLowerCase(Locale.ROOT);
359	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
360	            return false;
361	        }
362	        // Reject addresses whose domain is on the disposable-domain blocklist.
363	        String domain = normalized.substring(normalized.indexOf('@') + 1);
364	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
365	            return false;
366	        }
367	        ownerFieldsDto.setEmail(normalized);
368	        return true;
369	    }
370	
371	    /**
372	     * Validate the optional owner postcode in place.
373	     *
374	     * <p>An absent (or blank) postcode is allowed and is normalized to {@code null}.
375	     * When present it must be exactly 4 digits, and — when the owner's city maps to a
376	     * known region via {@link OwnerMapper#CITY_REGION} — it must fall within that
377	     * region's inclusive postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
378	     * A city with no known region accepts any 4-digit postcode. Returns {@code false}
379	     * when a postcode is present but malformed or out of range, so the caller can
380	     * reject with 400.
381	     */
382	    private boolean normalizePostcode(OwnerFieldsDto ownerFieldsDto) {
383	        String postcode = ownerFieldsDto.getPostcode();
384	        if (postcode == null || postcode.isBlank()) {
385	            ownerFieldsDto.setPostcode(null);
386	            return true;
387	        }
388	        if (!postcode.matches("\\d{4}")) {
389	            return false;
390	        }
391	        String region = OwnerMapper.CITY_REGION.get(ownerFieldsDto.getCity());
392	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
393	        if (range != null) {
394	            int value = Integer.parseInt(postcode);
395	            if (value < range[0] || value > range[1]) {
396	                return false;
397	            }
398	        }
399	        return true;
400	    }
401	
402	    /**
403	     * Validate and normalize the owner's address fields in place, preferring the structured
404	     * form over the flat 'address' for backward compatibility.
405	     *
406	     * <p>When a non-blank {@code addressLine1} is supplied it is the structured form: both
407	     * {@code addressLine1} and (when present) {@code addressLine2} are normalized and stored
408	     * back, and {@code address} is set to the composed value — the normalized addressLine1,
409	     * with a single space and the normalized addressLine2 appended when addressLine2 is present.
410	     * Otherwise the flat {@code address} is normalized in place and the structured lines are
411	     * cleared. Returns {@code false} when no address is supplied in either form (both the
412	     * structured addressLine1 and the flat address are blank once normalized), so the caller
413	     * can reject with 400.
414	     */
415	    private boolean normalizeAddresses(OwnerFieldsDto ownerFieldsDto) {
416	        String rawLine1 = ownerFieldsDto.getAddressLine1();
417	        if (rawLine1 != null && !rawLine1.isBlank()) {
418	            String line1 = normalizeAddress(rawLine1);
419	            if (line1.isBlank()) {
420	                return false;
421	            }
422	            ownerFieldsDto.setAddressLine1(line1);
423	            String rawLine2 = ownerFieldsDto.getAddressLine2();
424	            String composed = line1;
425	            if (rawLine2 != null && !rawLine2.isBlank()) {
426	                String line2 = normalizeAddress(rawLine2);
427	                ownerFieldsDto.setAddressLine2(line2);
428	                composed = line1 + " " + line2;
429	            }
430	            else {
431	                ownerFieldsDto.setAddressLine2(null);
432	            }
433	            ownerFieldsDto.setAddress(composed);
434	            return true;
435	        }
436	        // No structured address: fall back to the flat 'address' input.
437	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
438	        if (canonicalAddress.isBlank()) {
439	            return false;
440	        }
441	        ownerFieldsDto.setAddress(canonicalAddress);
442	        ownerFieldsDto.setAddressLine1(null);
443	        ownerFieldsDto.setAddressLine2(null);
444	        return true;
445	    }
446	
447	    /**
448	     * Normalize an owner address: trim, collapse each run of whitespace to a single
449	     * space, upper-case, and expand common street-type abbreviations
450	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
451	     * A {@code null} value normalizes to the empty string.
452	     */
453	    private static String normalizeAddress(String value) {
454	        if (value == null) {
455	            return "";
456	        }
457	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
458	        if (collapsed.isEmpty()) {
459	            return "";
460	        }
461	        String[] tokens = collapsed.split(" ");
462	        StringBuilder sb = new StringBuilder(collapsed.length());
463	        for (int i = 0; i < tokens.length; i++) {
464	            if (i > 0) {
465	                sb.append(' ');
466	            }
467	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
468	        }
469	        return sb.toString();
470	    }
471	
472	    /**
473	     * Normalize a telephone number to E.164 form.
474	     *
475	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
476	     * explicit leading {@code '+'} and country code it is kept; otherwise the
477	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
478	     * dropped from the national digits. The result must contain 8 to 15 digits
479	     * after the {@code '+'}, and — for a recognised country calling code — exactly
480	     * the national-number length that code mandates ({@code '+61'} => 9 national
481	     * digits, {@code '+1'} => 10).
482	     *
483	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
484	     *         the input is absent or cannot form a valid E.164 number.
485	     */
486	    private static String toE164(String raw) {
487	        if (raw == null) {
488	            return null;
489	        }
490	        String trimmed = raw.trim();
491	        boolean hasCountryCode = trimmed.startsWith("+");
492	        // Strip spaces, dashes and brackets.
493	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
494	        String digits;
495	        if (hasCountryCode) {
496	            // Keep the explicit country code; drop the leading '+' for validation.
497	            digits = stripped.substring(1);
498	        } else {
499	            // No country code: assume '+61' and drop a single leading '0'.
500	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
501	            digits = "61" + national;
502	        }
503	        if (!digits.matches("\\d{8,15}")) {
504	            return null;
505	        }
506	        // For a recognised country calling code, enforce the exact national-number length it
507	        // mandates (e.g. '+61' => 9 national digits, '+1' => 10). Longer codes win so a '+61'
508	        // number is not mistaken for a '+6...' one. Unknown codes keep the generic 8-15 rule.
509	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet().stream()
510	                .sorted((a, b) -> b.length() - a.length()).toList()) {
511	            if (digits.startsWith(countryCode)) {
512	                int nationalLength = digits.length() - countryCode.length();
513	                if (nationalLength != NATIONAL_NUMBER_LENGTHS.get(countryCode)) {
514	                    return null;
515	                }
516	                break;
517	            }
518	        }
519	        return "+" + digits;
520	    }
