536	    /**
537	     * Count the existing owners in the same household as the given owner, i.e. those sharing its
538	     * computed householdId (derived from the normalized last name and postcode). Used, together
539	     * with the owner being created, to derive the household size recorded on the owner.
540	     */
541	    private int countHouseholdMembers(Owner owner) {
542	        String householdId = ownerMapper.householdId(owner);
543	        return (int) this.clinicService.findAllOwners().stream()
544	            .filter(existing -> householdId.equals(ownerMapper.householdId(existing)))
545	            .count();
546	    }
547	
548	    /**
549	     * Compute the membership-level cap for the owner being created: one above the current maximum
550	     * effective membership level among its existing (non-deleted) household members, i.e. those
551	     * sharing its computed householdId. Each member's effective level is read through
552	     * {@link OwnerMapper#membershipLevel(Owner)}, so it already reflects any cap applied to that
553	     * member. Returns {@code null} when the owner has no existing household member, in which case
554	     * no cap applies.
555	     */
556	    private Integer membershipLevelCap(Owner owner) {
557	        String householdId = ownerMapper.householdId(owner);
558	        java.util.OptionalInt maxLevel = this.clinicService.findAllOwners().stream()
559	            .filter(existing -> !existing.isDeleted())
560	            .filter(existing -> existing != owner)
561	            .filter(existing -> householdId.equals(ownerMapper.householdId(existing)))
562	            .mapToInt(existing -> ownerMapper.membershipLevel(existing))
563	            .max();
564	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
565	    }
566	
567	    /**
568	     * Find an existing owner that the given (not-yet-created) owner is a possible (soft) duplicate
569	     * of: one whose identity key differs (so it is not a hard duplicate) yet whose last name shares
570	     * the same Soundex code and whose postcode is the same. Owners without a postcode never match
571	     * (the postcode must be shared) and deleted owners are ignored. When several existing owners
572	     * match, the one with the lowest id is returned so the result is deterministic. Returns
573	     * {@code null} when there is no such match.
574	     */
575	    private Owner findPossibleDuplicate(Owner candidate) {
576	        if (candidate.getPostcode() == null) {
577	            return null;
578	        }
579	        String candidateKey = ownerMapper.identityKey(candidate);
580	        String candidateSoundex = Soundex.of(candidate.getLastName());
581	        return this.clinicService.findAllOwners().stream()
582	            .filter(existing -> !existing.isDeleted())
583	            .filter(existing -> !candidateKey.equals(ownerMapper.identityKey(existing)))
584	            .filter(existing -> candidate.getPostcode().equals(existing.getPostcode())
585	                && candidateSoundex.equals(Soundex.of(existing.getLastName())))
586	            .min(java.util.Comparator.comparing(Owner::getId))
587	            .orElse(null);
588	    }
589	
590	    /**
591	     * Build the owner's customer code, formatted {@code '<REGION>-<HASH8>'}.
592	     *
593	     * <p>{@code REGION} is the region derived from the owner's postcode (see
594	     * {@link #deriveRegion}). {@code HASH8} is the first 8 upper-case hex characters of the
595	     * SHA-256 of the normalized telephone concatenated with the last name
596	     * (e.g. {@code 'NSW-1A2B3C4D'}).
597	     *
598	     * <p>When the computed code collides with an existing owner's customer code, it is
599	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more
600	     * that makes it unique.
601	     */
602	    /**
603	     * The owner's current primary identifier, as carried by structured audit events. Today this
604	     * is the customerCode; when the customerCode is later unified into a memberId, updating this
605	     * one method makes every emitted event carry the memberId instead.
606	     */
607	    private String primaryIdentifier(Owner owner) {
608	        return owner.getCustomerCode();
609	    }
610	
611	    private String customerCode(Owner owner) {
612	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
613	        String hash8 = sha256HexUpper(owner.getTelephone() + owner.getLastName(), 8);
614	        String base = region + "-" + hash8;
615	        Set<String> existing = this.clinicService.findAllOwners().stream()
616	            .map(Owner::getCustomerCode)
617	            .filter(java.util.Objects::nonNull)
618	            .collect(Collectors.toSet());
619	        if (!existing.contains(base)) {
620	            return base;
621	        }
622	        int n = 2;
623	        while (existing.contains(base + "-" + n)) {
624	            n++;
625	        }
626	        return base + "-" + n;
627	    }
628	
629	    /**
630	     * Derive the owner's region, preferring the postcode. The postcode is matched against
631	     * each region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); only when
632	     * it is absent or in no known range does this fall back to the fixed city-to-region table
633	     * (see {@link OwnerMapper#CITY_REGION}), and finally {@code 'UNKNOWN'}.
634	     */
635	    private static String deriveRegion(String postcode, String city) {
636	        if (postcode != null && postcode.matches("\\d{4}")) {
637	            int value = Integer.parseInt(postcode);
638	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
639	                int[] range = entry.getValue();
640	                if (value >= range[0] && value <= range[1]) {
641	                    return entry.getKey();
642	                }
643	            }
644	        }
645	        return OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
646	    }
647	
648	    /**
649	     * The first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
650	     * bytes of {@code value}.
651	     */
652	    private static String sha256HexUpper(String value, int length) {
653	        try {
654	            byte[] digest = MessageDigest.getInstance("SHA-256")
655	                .digest(value.getBytes(StandardCharsets.UTF_8));
656	            StringBuilder sb = new StringBuilder(digest.length * 2);
657	            for (byte b : digest) {
658	                sb.append(String.format("%02X", b));
659	            }
660	            return sb.substring(0, length);
661	        }
662	        catch (NoSuchAlgorithmException e) {
663	            throw new IllegalStateException(e);
664	        }
665	    }
666	
667	    /**
668	     * Count the existing owners located in the given city, compared case-insensitively.
669	     * Used to derive the per-city 4-digit sequence in the customer code.
670	     */
671	    private int countOwnersInCity(String city) {
672	        return (int) this.clinicService.findAllOwners().stream()
673	            .filter(existing -> existing.getCity() != null
674	                && existing.getCity().equalsIgnoreCase(city))
675	            .count();
676	    }
677	
678	    /**
679	     * Count the existing owners whose registration date is the given (adjusted business) date.
680	     * Used to enforce the per-day sign-up limit.
681	     */
682	    private int countOwnersRegisteredOn(LocalDate date) {
683	        return (int) this.clinicService.findAllOwners().stream()
684	            .filter(existing -> date.equals(existing.getRegistrationDate()))
685	            .count();
686	    }
687	
688	    /** Fixed public holidays the business-day roll skips. */
689	    private static final Set<LocalDate> HOLIDAYS = Set.of(
690	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
691	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
692	        LocalDate.parse("2026-12-28"));
693	
694	    /**
695	     * Roll a registration date forward onto a business day: a Saturday, Sunday, or listed
696	     * public holiday is moved forward to the next non-holiday weekday; a plain weekday is
697	     * returned unchanged.
698	     */
699	    private static LocalDate toBusinessDay(LocalDate date) {
700	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
701	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
702	            || HOLIDAYS.contains(date)) {
703	            date = date.plusDays(1);
704	        }
705	        return date;
706	    }
