5	/**
6	 * American Soundex coder used to reduce a surname to a phonetic code. Kept in its own
7	 * class (rather than as a method on {@link OwnerMapper}) so MapStruct does not mistake a
8	 * {@code String -> String} helper for an implicit property mapping method.
9	 */
10	public final class Soundex {
11	
12	    private Soundex() {
13	    }
14	
15	    /**
16	     * The American Soundex code of a name: its first letter followed by three digits
17	     * encoding the remaining consonants (b,f,p,v=1; c,g,j,k,q,s,x,z=2; d,t=3; l=4;
18	     * m,n=5; r=6), with adjacent equal codes (and codes separated only by h/w) collapsed
19	     * and vowels acting as separators. The result is upper-cased and padded with trailing
20	     * zeros to exactly four characters. A {@code null}/blank or letter-less name yields the
21	     * empty string.
22	     */
23	    public static String of(String value) {
24	        if (value == null) {
25	            return "";
26	        }
27	        String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
28	        if (letters.isEmpty()) {
29	            return "";
30	        }
31	        StringBuilder code = new StringBuilder();
32	        code.append(letters.charAt(0));
33	        char previous = codeOf(letters.charAt(0));
34	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
35	            char c = letters.charAt(i);
36	            if (c == 'H' || c == 'W') {
37	                // Transparent: does not emit a digit nor reset the previous code.
38	                continue;
39	            }
40	            char digit = codeOf(c);
41	            if (digit != '0' && digit != previous) {
42	                code.append(digit);
43	            }
44	            // Vowels ('0') reset the run so a later equal consonant is coded again.
45	            previous = digit;
46	        }
47	        while (code.length() < 4) {
48	            code.append('0');
49	        }
50	        return code.toString();
51	    }
52	
53	    private static char codeOf(char c) {
54	        return switch (c) {
55	            case 'B', 'F', 'P', 'V' -> '1';
56	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
57	            case 'D', 'T' -> '3';
58	            case 'L' -> '4';
59	            case 'M', 'N' -> '5';
60	            case 'R' -> '6';
61	            default -> '0';
62	        };
63	    }
64	}
