221	        // Reject the create when the owner's city is already at capacity, i.e. it already
222	        // contains 50 or more owners (compared case-insensitively).
223	        int ownersInCity = countOwnersInCity(ownerFieldsDto.getCity());
224	        if (ownersInCity >= 50) {
225	            return new ResponseEntity<>(HttpStatus.CONFLICT);
226	        }
227	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
228	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
229	        if (normalizedTelephone == null) {
230	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
231	        }
232	        ownerFieldsDto.setTelephone(normalizedTelephone);
233	        // Consolidated duplicate detection. All duplicate checks are now expressed through the
234	        // single derived identity key: the SHA-256 hex of
235	        // '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>' (see OwnerMapper#identityKey).
236	        // A create is rejected with 409 only when the new owner's identity key collides with an
237	        // existing (non-deleted) owner's. Because the telephone is part of the key, two owners with
238	        // the same last name and postcode but different telephones no longer collide — they are
239	        // created (and may be flagged as a soft match below), not rejected. The former separate
240	        // household-duplicate 409 keyed on the computed householdId no longer applies.
241	        Owner candidate = ownerMapper.toOwner(ownerFieldsDto);
242	        String identityKey = ownerMapper.identityKey(candidate);
243	        boolean identityInUse = this.clinicService.findAllOwners().stream()
244	            .filter(existing -> !existing.isDeleted())
245	            .anyMatch(existing -> identityKey.equals(ownerMapper.identityKey(existing)));
246	        if (identityInUse) {
247	            return new ResponseEntity<>(HttpStatus.CONFLICT);
248	        }
249	        // Determine the effective registration date — the value supplied on the request, or the
250	        // server's current date when none was supplied — and roll it forward to the next business
251	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
252	        // registration date (membership-number year segment, per-day create-limit) uses this
253	        // adjusted date.
254	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
255	        if (registrationDate == null) {
256	            registrationDate = LocalDate.now();
257	        }
258	        // Reject a supplied registration date that lies in the future (later than the
259	        // server's current date): an owner cannot be registered ahead of time.
260	        else if (registrationDate.isAfter(LocalDate.now())) {
261	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
262	        }
263	        registrationDate = toBusinessDay(registrationDate);
264	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
265	        // owners have already been registered on this (adjusted) business day.
266	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
267	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
268	        }
269	        HttpHeaders headers = new HttpHeaders();
270	        Owner owner = candidate;
271	        owner.setRegistrationDate(registrationDate);
272	        // Assign the customer code as '<REGION>-<HASH8>': the region derived from the owner's
273	        // postcode (falling back to the city, then 'UNKNOWN') and the first 8 upper-case hex
274	        // characters of the SHA-256 of the normalized telephone concatenated with the last name.
275	        owner.setCustomerCode(customerCode(owner));
276	        // Record how many existing owners already share this owner's first and last name
277	        // (compared case-insensitively) at the moment before this owner is created.
278	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
279	        // Flag a bulk sign-up when more than 80 owners have already been created today, i.e.
280	        // registered on this (adjusted) business day before this owner is created.
281	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > 80);
282	        // Flag that the owner's city is approaching its capacity limit: it already held between
283	        // 40 and 49 owners (inclusive) before this owner was created. The hard rejection at 50
284	        // owners is handled above, so reaching this point means the count is below 50.
285	        owner.setCapacityWarning(ownersInCity >= 40 && ownersInCity < 50);
286	        // Record the size of this owner's household after this create: the number of existing
287	        // owners sharing the same household (i.e. the same computed householdId) plus this owner.
288	        owner.setHouseholdSize(countHouseholdMembers(owner) + 1);
289	        // Cap this owner's membership level at one above the current maximum membership level among
290	        // their existing household members. When the owner has no existing household member no cap
291	        // applies (a null cap; see OwnerMapper#membershipLevel).
292	        owner.setMembershipLevelCap(membershipLevelCap(owner));
293	        // Flag a possible (soft) duplicate: this owner is not a hard identity duplicate (its
294	        // identity key is distinct), but it shares an existing owner's Soundex last name and
295	        // postcode. When such a match exists, record it as 'possibleDuplicate' with
296	        // 'possibleDuplicateOf' set to the matching owner's id; otherwise it is not a possible
297	        // duplicate. A declared household member (the request sets 'sharesHousehold') is an
298	        // acknowledged member, not a suspected duplicate, so it is never flagged.
299	        Owner softMatch = findPossibleDuplicate(owner);
300	        boolean declaredMember = softMatch != null && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
301	        if (declaredMember) {
302	            owner.setPossibleDuplicate(false);
303	            owner.setPossibleDuplicateOf(null);
304	        }
305	        else {
306	            owner.setPossibleDuplicate(softMatch != null);
307	            owner.setPossibleDuplicateOf(softMatch == null ? null : softMatch.getId());
308	        }
309	        this.clinicService.saveOwner(owner);
310	        // Emit an audit line recording the new owner's id, customer code, registration date,
311	        // membership level and membership number.
312	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
313	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
314	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
315	        // Emit the immutable structured OWNER_CREATED event carrying a monotonically increasing
316	        // sequence and the owner's current primary identifier (the customerCode today).
317	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_SEQ.incrementAndGet(), owner.getId(),
318	            primaryIdentifier(owner), ownerMapper.membershipLevel(owner), "OWNER_CREATED");
319	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
320	        // Remember this create against its idempotency key so a later repeat returns the same
321	        // owner instead of creating a duplicate.
322	        if (idempotencyKey != null) {
323	            idempotentCreates.put(idempotencyKey, owner.getId());
324	        }
325	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
326	        headers.setLocation(UriComponentsBuilder.newInstance()
327	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
328	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
329	    }
