344	    /**
345	     * Validate and normalize the optional owner email in place.
346	     *
347	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
348	     * When present it must be a syntactically valid address; a valid address is
349	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
350	     * present but syntactically invalid, so the caller can reject with 400.
351	     */
352	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
353	        String email = ownerFieldsDto.getEmail();
354	        if (email == null || email.isBlank()) {
355	            ownerFieldsDto.setEmail(null);
356	            return true;
357	        }
358	        String normalized = email.trim().toLowerCase(Locale.ROOT);
359	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
360	            return false;
361	        }
362	        // Reject addresses whose domain is on the disposable-domain blocklist.
363	        String domain = normalized.substring(normalized.indexOf('@') + 1);
364	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
365	            return false;
366	        }
367	        ownerFieldsDto.setEmail(normalized);
368	        return true;
369	    }
