371	    /**
372	     * Validate the optional owner postcode in place.
373	     *
374	     * <p>An absent (or blank) postcode is allowed and is normalized to {@code null}.
375	     * When present it must be exactly 4 digits, and — when the owner's city maps to a
376	     * known region via {@link OwnerMapper#CITY_REGION} — it must fall within that
377	     * region's inclusive postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
378	     * A city with no known region accepts any 4-digit postcode. Returns {@code false}
379	     * when a postcode is present but malformed or out of range, so the caller can
380	     * reject with 400.
381	     */
382	    private boolean normalizePostcode(OwnerFieldsDto ownerFieldsDto) {
383	        String postcode = ownerFieldsDto.getPostcode();
384	        if (postcode == null || postcode.isBlank()) {
385	            ownerFieldsDto.setPostcode(null);
386	            return true;
387	        }
388	        if (!postcode.matches("\\d{4}")) {
389	            return false;
390	        }
391	        String region = OwnerMapper.CITY_REGION.get(ownerFieldsDto.getCity());
392	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
393	        if (range != null) {
394	            int value = Integer.parseInt(postcode);
395	            if (value < range[0] || value > range[1]) {
396	                return false;
397	            }
398	        }
399	        return true;
400	    }
