402	    /**
403	     * Validate and normalize the owner's address fields in place, preferring the structured
404	     * form over the flat 'address' for backward compatibility.
405	     *
406	     * <p>When a non-blank {@code addressLine1} is supplied it is the structured form: both
407	     * {@code addressLine1} and (when present) {@code addressLine2} are normalized and stored
408	     * back, and {@code address} is set to the composed value — the normalized addressLine1,
409	     * with a single space and the normalized addressLine2 appended when addressLine2 is present.
410	     * Otherwise the flat {@code address} is normalized in place and the structured lines are
411	     * cleared. Returns {@code false} when no address is supplied in either form (both the
412	     * structured addressLine1 and the flat address are blank once normalized), so the caller
413	     * can reject with 400.
414	     */
415	    private boolean normalizeAddresses(OwnerFieldsDto ownerFieldsDto) {
416	        String rawLine1 = ownerFieldsDto.getAddressLine1();
417	        if (rawLine1 != null && !rawLine1.isBlank()) {
418	            String line1 = normalizeAddress(rawLine1);
419	            if (line1.isBlank()) {
420	                return false;
421	            }
422	            ownerFieldsDto.setAddressLine1(line1);
423	            String rawLine2 = ownerFieldsDto.getAddressLine2();
424	            String composed = line1;
425	            if (rawLine2 != null && !rawLine2.isBlank()) {
426	                String line2 = normalizeAddress(rawLine2);
427	                ownerFieldsDto.setAddressLine2(line2);
428	                composed = line1 + " " + line2;
429	            }
430	            else {
431	                ownerFieldsDto.setAddressLine2(null);
432	            }
433	            ownerFieldsDto.setAddress(composed);
434	            return true;
435	        }
436	        // No structured address: fall back to the flat 'address' input.
437	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
438	        if (canonicalAddress.isBlank()) {
439	            return false;
440	        }
441	        ownerFieldsDto.setAddress(canonicalAddress);
442	        ownerFieldsDto.setAddressLine1(null);
443	        ownerFieldsDto.setAddressLine2(null);
444	        return true;
445	    }
