708	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
709	    @Override
710	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
711	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
712	        if (currentOwner == null) {
713	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
714	        }
715	        if (!normalizeEmail(ownerFieldsDto)) {
716	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
717	        }
718	        if (!normalizePostcode(ownerFieldsDto)) {
719	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
720	        }
721	        if (!normalizeAddresses(ownerFieldsDto)) {
722	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
723	        }
724	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
725	        if (normalizedTelephone == null) {
726	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
727	        }
728	        currentOwner.setAddress(ownerFieldsDto.getAddress());
729	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
730	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
731	        currentOwner.setCity(ownerFieldsDto.getCity());
732	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
733	        currentOwner.setLastName(ownerFieldsDto.getLastName());
734	        currentOwner.setTelephone(normalizedTelephone);
735	        currentOwner.setEmail(ownerFieldsDto.getEmail());
736	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
737	        this.clinicService.saveOwner(currentOwner);
738	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
739	    }
740	
741	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
742	    @Transactional
743	    @Override
744	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
745	        Owner owner = this.clinicService.findOwnerById(ownerId);
746	        if (owner == null) {
747	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
748	        }
749	        // Soft-delete: flag the owner deleted and retain the record so it can still be
750	        // read back (with 'deleted' true) and is ignored by later duplicate/identity checks.
751	        owner.setDeleted(true);
752	        this.clinicService.saveOwner(owner);
753	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
754	    }
755	
756	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
757	    @Override
758	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
759	        Owner owner = this.clinicService.findOwnerById(ownerId);
760	        if (owner == null) {
761	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
762	        }
763	        HttpHeaders headers = new HttpHeaders();
764	        Pet pet = petMapper.toPet(petFieldsDto);
765	        owner.setId(ownerId);
766	        pet.setOwner(owner);
767	        pet.getType().setName(null);
768	        this.clinicService.savePet(pet);
769	        PetDto petDto = petMapper.toPetDto(pet);
770	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
771	            .buildAndExpand(pet.getId()).toUri());
772	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
773	    }
774	
775	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
776	    @Override
777	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
778	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
779	        if (currentOwner != null) {
780	            Pet currentPet = this.clinicService.findPetById(petId);
781	            if (currentPet != null) {
782	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
783	                currentPet.setName(petFieldsDto.getName());
784	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
785	                this.clinicService.savePet(currentPet);
786	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
787	            }
788	        }
789	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
790	    }
