793	    @Override
794	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
795	        HttpHeaders headers = new HttpHeaders();
796	        Visit visit = visitMapper.toVisit(visitFieldsDto);
797	        Pet pet = new Pet();
798	        pet.setId(petId);
799	        visit.setPet(pet);
