63	     * title was supplied (e.g. 'DR Who'), or just the last name when no title (null or blank)
64	     * was given.
65	     */
66	    default String salutation(Owner owner) {
67	        String title = owner.getTitle();
68	        if (title == null || title.isBlank()) {
69	            return owner.getLastName();
